import java.util.HashMap;
import java.util.Map;

class Main {
    public static void main(String[] args) {
        String text = "Java is great. Java is powerful. I love Java programming.";
        Map<String, Integer> wordCount = new HashMap<>();

        String[] words = text.toLowerCase().split("\s+");

        for (String word : words) {
            String cleaned = word.replaceAll("[^a-z0-9]", "");

            if (!cleaned.isEmpty()) {
                wordCount.put(cleaned, wordCount.getOrDefault(cleaned, 0) + 1);
            }
        }

        System.out.println("原文本: " + text + "
");
        System.out.println("单词频率:");

        for (Map.Entry<String, Integer> entry : wordCount.entrySet()) {
            System.out.println(entry.getKey() + ": " + entry.getValue());
        }
    }
}
